/**
 * Draft cards without saving anything.
 *
 * The chat model does not write the cards, and since the one-step tool it does not
 * read them either. It decides what is wanted and where it should go; the cards
 * are generated by the one-shot functions the app already uses, on the cheap
 * model, and go straight from here to the screen as `show_card_drafts`. The long
 * structured output never passes through the chat model in either direction — not
 * as a tool result to read, and not as component props to copy back out, which is
 * what it used to do at five times the input price and with a card dropped or
 * reworded now and then.
 *
 * Nothing here touches the database. Only what the person ticks is ever saved.
 *
 * Questions are not generated here. `generate-questions` verifies its lesson and
 * card ids against the database, so it cannot run on cards that do not exist yet;
 * practice questions are made after the cards land.
 */

import { z } from 'npm:zod@^4.3.6';

/** How much material one draft may be made from. Long enough for a page of notes
 *  said back by the model, short enough that it is not a document by another door. */
export const TOPIC_MAX = 4000;

/** Past this the material is a passage to take cards out of, not a subject to
 *  write cards about. The generators treat the two differently — "generate terms
 *  for the topic X" against "extract the terms from this text" — and a paragraph
 *  handed over as a topic comes back as cards about the paragraph's subject at
 *  large rather than about what the paragraph says. */
export const PASSAGE_FROM = 240;

export const draftLessonInput = z.object({
  topic: z.string().trim().min(1).max(TOPIC_MAX),
  learning_mode: z.enum(['knowledge', 'language']).default('knowledge'),
  card_count: z.number().int().min(1).max(50).optional(),
}).strict();

export type DraftLessonArgs = z.output<typeof draftLessonInput>;

/** The extra a language card carries: how it sounds, how it is used, what it
 *  belongs with. Shaped like `terms.language_data`, because that is where it ends
 *  up. Kept loose here — the generator owns the shape, and this only carries it. */
export type LanguageDetails = Record<string, unknown>;

export type DraftCard = {
  /** Local to this draft and stable within it; what a selection refers to. Not a
   *  database id, because nothing has been written. */
  id: string;
  term: string;
  definition: string;
  explanation?: string | null;
  /** Language mode only. The model never sees it; it goes to the screen. */
  language_data?: LanguageDetails | null;
};

export type DraftResult = {
  cards: DraftCard[];
  learning_mode: 'knowledge' | 'language';
  /** Echoed back so the model can name the lesson from what was actually asked. */
  topic: string;
};

export type DraftContext = {
  fetch: typeof fetch;
  /** e.g. https://<project>.supabase.co/functions/v1 */
  functionsUrl: string;
  /** The caller's own bearer token: generation runs with their privileges, not ours. */
  authorization: string;
  /**
   * Proof to the generator that this is chat asking, so the draft is not counted
   * a second time as one of the person's generated lessons (aiGate.ts). Made per
   * call, because it is only good for a few minutes. Absent, the generator treats
   * this like any other request — which is the safe way to be without it.
   */
  internal?: () => Promise<string | null>;
};

type GeneratedTerm = {
  term?: unknown;
  definition?: unknown;
  explanation?: unknown;
  language_data?: unknown;
};

/** The same two generators the create screen picks between, so a card drafted in
 *  chat is the same kind of card as one drafted there. */
export function generatorFor(mode: 'knowledge' | 'language'): string {
  return mode === 'language' ? 'generate-vocab-terms' : 'generate-terms';
}

export async function draftLesson(args: DraftLessonArgs, ctx: DraftContext): Promise<DraftResult> {
  const mode = args.learning_mode;
  // The generators take free text and decide the count themselves, so a requested
  // number can only be asked for, not set.
  const content = args.card_count
    ? `${args.topic}\n\n(About ${args.card_count} cards.)`
    : args.topic;

  const signed = ctx.internal ? await ctx.internal().catch(() => null) : null;
  const response = await ctx.fetch(`${ctx.functionsUrl}/${generatorFor(mode)}`, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json', Authorization: ctx.authorization,
      ...(signed ? { 'x-memq-internal': signed } : {}),
    },
    body: JSON.stringify({ type: args.topic.length > PASSAGE_FROM ? 'text' : 'topic', content }),
  });

  if (!response.ok) {
    // Say what the person can act on, not what the provider said.
    throw new Error('Could not draft cards just now. Try again, or say it a different way.');
  }

  let payload: { results?: unknown };
  try {
    payload = await response.json();
  } catch {
    throw new Error('Could not draft cards just now. Try again, or say it a different way.');
  }

  const raw = Array.isArray(payload.results) ? payload.results as GeneratedTerm[] : [];
  const cards: DraftCard[] = [];
  for (const item of raw) {
    if (!item || typeof item.term !== 'string' || typeof item.definition !== 'string') continue;
    const term = item.term.trim();
    const definition = item.definition.trim();
    if (!term || !definition) continue;
    const explanation = typeof item.explanation === 'string' && item.explanation.trim()
      ? item.explanation.trim() : null;
    const details = item.language_data && typeof item.language_data === 'object' && !Array.isArray(item.language_data)
      ? item.language_data as LanguageDetails : null;
    cards.push({ id: `d${cards.length + 1}`, term, definition, explanation, language_data: details });
    // The component draws at most this many, and a draft nobody can read is no use.
    if (cards.length >= 50) break;
  }

  if (!cards.length) {
    throw new Error('Nothing useful came out of that. Ask for something more specific, or give more detail.');
  }

  return { cards, learning_mode: mode, topic: args.topic };
}
